import fs from "node:fs";
const cards = JSON.parse(fs.readFileSync("src/data/flashcards.json", "utf8"));
const questions = JSON.parse(
  fs.readFileSync("src/data/quiz-private.json", "utf8"),
);
const id = (prefix, index) =>
  `${prefix}0000000-0000-4000-8000-${String(index + 1).padStart(12, "0")}`;
const sql = (value) => `'${String(value).replaceAll("'", "''")}'`;
const rows = [
  "-- Curated independent practice content. Generated by scripts/generate-seed.mjs.",
  "begin;",
];
for (const [i, level] of ["n5", "n4", "n3", "n2", "n1"].entries())
  rows.push(
    `insert into public.courses(id,slug,title,published) values(${sql(id(6, i))},${sql(level)},${sql("JLPT " + level.toUpperCase())},${i < 2}) on conflict do nothing;`,
  );
for (const [i, level] of ["n5", "n4"].entries())
  rows.push(
    `insert into public.flashcard_decks(id,course_id,title,published) values(${sql(id(2, i))},${sql(id(6, i))},${sql(level.toUpperCase() + " vocabulary")},true) on conflict do nothing;`,
  );
for (const [i, card] of cards.entries())
  rows.push(
    `insert into public.flashcards(id,deck_id,term,reading,translations,example,example_translation,position) values(${sql(id(1, i))},${sql(id(2, card.level === "n5" ? 0 : 1))},${sql(card.term)},${sql(card.reading)},${sql(JSON.stringify(card.translations))}::jsonb,${sql(card.example)},${sql(card.exampleTranslation)},${i % 10}) on conflict do nothing;`,
  );
rows.push(
  `insert into public.question_banks(id,course_id,title,published) values(${sql(id(3, 0))},${sql(id(6, 1))},'N4 grammar practice',true) on conflict do nothing;`,
);
for (const [i, q] of questions.entries()) {
  if (
    q.options.length !== 4 ||
    new Set(q.options).size !== 4 ||
    !Number.isInteger(q.correctIndex) ||
    q.correctIndex < 0 ||
    q.correctIndex > 3
  )
    throw new Error("Invalid quiz content");
  rows.push(
    `insert into public.questions(id,bank_id,prompt,position) values(${sql(id(4, i))},${sql(id(3, 0))},${sql(q.prompt)},${i}) on conflict do nothing;`,
  );
  for (const [j, text] of q.options.entries())
    rows.push(
      `insert into public.question_options(id,question_id,text,position) values(${sql(id(5, i * 4 + j))},${sql(id(4, i))},${sql(text)},${j}) on conflict do nothing;`,
    );
  rows.push(
    `insert into private.answer_keys(question_id,option_id,explanation,japanese_explanation,translation) values(${sql(id(4, i))},${sql(id(5, i * 4 + q.correctIndex))},${sql(q.explanation)},${sql(q.japaneseExplanation)},${sql(q.translation)}) on conflict do nothing;`,
  );
}
rows.push("commit;");
fs.writeFileSync(
  "supabase/migrations/202610220002_curated_content.sql",
  rows.join("\n") + "\n",
);
